/* ne_detect.c - name-entry (kana selection) screen detector implementation.
 *
 * Signature: small glyph-shaped patches taken from the character-selection
 * grid of the name-entry screen (x in [24,112], the grid proper, distinct
 * from the empty entered-name field at x > 120). Each patch is an anchor
 * plus a set of (dx,dy,want_dark) checks. Dark positions must be opaque
 * black (glyph); non-dark positions must not be black (background).
 *
 * Verified stable across both name-entry cursor-position references and
 * outside cursor/highlight areas. Rejects char-select, title, gameplay, the
 * boot false-positive frame, fully-black frames, and uniform-background
 * frames.
 *
 * Regression requirement: char-select.png -> false.
 *
 * Valid only for the 256x240 native ARGB8888 frame (cyc_frame_argb()),
 * never the composed/presented buffer.
 */

#include "ne_detect.h"

struct ne_check { int dx, dy; int want_dark; };

struct ne_patch { int x, y; int check_count; const struct ne_check *checks; };

/* anchor (35,121) */
static const struct ne_check s_patch0[] = {
    { 0, 0, 1 }, { 0, -1, 1 }, { -5, -5, 0 }, { 5, -5, 0 },
};
/* anchor (83,137) */
static const struct ne_check s_patch1[] = {
    { 0, 0, 1 }, { -1, 0, 1 }, { -5, -5, 0 }, { 5, -5, 0 },
};
/* anchor (97,169) */
static const struct ne_check s_patch2[] = {
    { 0, 0, 1 }, { 0, -1, 1 }, { -5, -5, 0 }, { 5, -5, 0 },
};
/* anchor (65,169) */
static const struct ne_check s_patch3[] = {
    { 0, 0, 1 }, { 0, -1, 1 }, { -5, -5, 0 }, { 5, -5, 0 },
};
/* anchor (49,121) */
static const struct ne_check s_patch4[] = {
    { 0, 0, 1 }, { 0, -1, 1 }, { -5, -5, 0 }, { 5, -5, 0 },
};

static const struct ne_patch s_ne_patches[] = {
    { 35, 121, 4, s_patch0 },
    { 83, 137, 4, s_patch1 },
    { 97, 169, 4, s_patch2 },
    { 65, 169, 4, s_patch3 },
    { 49, 121, 4, s_patch4 },
};
#define NE_PATCH_COUNT (sizeof(s_ne_patches) / sizeof(s_ne_patches[0]))

#define NE_BLACK 0xFF000000u  /* opaque black (ARGB8888) */

int ne_detect_name_entry(const uint32_t *frame, int w, int h) {
    if (!frame || w < 256 || h < 240) return 0;
    for (size_t i = 0; i < NE_PATCH_COUNT; ++i) {
        const struct ne_patch *p = &s_ne_patches[i];
        for (int j = 0; j < p->check_count; ++j) {
            const struct ne_check *c = &p->checks[j];
            int xx = p->x + c->dx;
            int yy = p->y + c->dy;
            if (xx < 0 || xx >= w || yy < 0 || yy >= h) return 0;
            int is_dark = (frame[(size_t)yy * (size_t)w + (size_t)xx] == NE_BLACK);
            if (c->want_dark && !is_dark) return 0;
            if (!c->want_dark && is_dark) return 0;
        }
    }
    return 1;
}

/* Character-selection detector.
 *
 * Distinctive structure patches on the ORIGINAL frame (cyc_frame_argb()),
 * never the composed buffer:
 *   - Pink outer background corners (char select uses pink BG outside the
 *     orange box; name entry/title use light blue, gameplay is different).
 *   - Dark Japanese-label text pixels inside each of the five label boxes,
 *     plus non-dark background pixels adjacent to them.
 *
 * Portrait pixels are NOT used: they change when the selection highlight
 * moves, which made the detector selection-dependent. These patches are
 * stable across all five character-selection cursor states (verified
 * against cs_ultraman..cs_baltan.raw).
 *
 * Re-evaluated every call; no state/latching. Verified against the captured
 * page-1 char-select states only.
 */
struct cs_patch { int x, y; uint32_t color; int want_match; };

static const struct cs_patch s_cs_patches[] = {
    {  0,   0, 0xFFFF65A7u, 1 },   /* outer corner: pink (255,101,167) */
    { 252, 236, 0xFFFF65A7u, 1 },  /* outer corner: pink */
    { 51,  91, 0xFF000000u, 1 },   /* ULTRAMAN label: dark text */
    { 39,  88, 0xFF000000u, 0 },   /* near ULTRAMAN label: non-dark bg */
    { 177, 91, 0xFF000000u, 1 },   /* ULTRASEVEN label: dark text */
    { 199, 88, 0xFF000000u, 0 },   /* near ULTRASEVEN label: non-dark bg */
    { 65,  203, 0xFF000000u, 1 },  /* TARO label: dark text */
    { 47,  200, 0xFF000000u, 0 },  /* near TARO label: non-dark bg */
    { 113, 203, 0xFF000000u, 1 },  /* ACE label: dark text */
    { 111, 200, 0xFF000000u, 0 },  /* near ACE label: non-dark bg */
    { 179, 202, 0xFF000000u, 1 },  /* BALTAN label: dark text */
    { 175, 200, 0xFF000000u, 0 },  /* near BALTAN label: non-dark bg */
};
#define CS_PATCH_COUNT (sizeof(s_cs_patches) / sizeof(s_cs_patches[0]))

static int cs_channel_diff(uint32_t a, uint32_t b) {
    int da = (int)((a >> 16) & 0xFF) - (int)((b >> 16) & 0xFF);
    int db = (int)((a >> 8) & 0xFF) - (int)((b >> 8) & 0xFF);
    int dc = (int)(a & 0xFF) - (int)(b & 0xFF);
    if (da < 0) da = -da;
    if (db < 0) db = -db;
    if (dc < 0) dc = -dc;
    return da > db ? (da > dc ? da : dc) : (db > dc ? db : dc);
}

int ne_detect_char_select(const uint32_t *frame, int w, int h) {
    if (!frame || w < 256 || h < 240) return 0;
    for (size_t i = 0; i < CS_PATCH_COUNT; ++i) {
        const struct cs_patch *p = &s_cs_patches[i];
        if (p->x < 0 || p->x >= w || p->y < 0 || p->y >= h) return 0;
        uint32_t c = frame[(size_t)p->y * (size_t)w + (size_t)p->x];
        int match = (cs_channel_diff(c, p->color) <= 12);
        if (p->want_match && !match) return 0;
        if (!p->want_match && match) return 0;
    }
    return 1;
}

/* ---- Page-specific char-select detectors ----
 *
 * Each detector uses pink corners (common to all char-select pages) plus
 * page-unique label/structure patches. Detection is against cyc_frame_argb(),
 * re-evaluated every call, no latching.
 *
 * Page identification (pixel values verified against cs_page2..cs_page5.raw):
 *
 *   Page 1 (うるとらまん/せぶん/たろう/えーす/ばるたん):
 *     TL_a(45,90)=BG  AND  TR_a(178,90)=dark  AND  BL_c(68,204)=BG
 *
 *   Page 2 (あわじくっす/MK-2/にゃーがんたむ/じゃくしきかい/じゅあんぐ):
 *     TL_a(45,90)=BG  AND  BL_a(50,202)=dark  AND  TR_a(178,90)=BG
 *     AND  bg_BL(47,200)=BG
 *
 *   Page 3 (たーほろは/みゅうしゃさんく/ぐれーと5/ちゅうろは/しるは):
 *     BL_a(50,202)=BG  AND  BL_c(68,204)=BG  AND  BR_b(190,203)=dark
 *
 *   Page 4 (らいだー1ごう/らいだー2ごう/V3/RX/しゃどーむーん):
 *     TL_a(45,90)=dark  AND  TR_a(178,90)=dark
 *
 *   Page 5 (two light-on-black name panels + message panel):
 *     bg_BL(47,200)=dark  AND  bg_BC(111,200)=dark  AND  bg_BR(175,200)=dark
 *
 * Detection order: page 5 -> page 4 -> page 3 -> page 2 -> page 1.
 * Pages are mutually exclusive; none match on non-char-select screens.
 */

#define CS_BG_COLOR 0xFFC0D8FFu  /* light blue background (192,216,255) */
#define CS_PINK_COLOR 0xFFFF65A7u /* pink outer background (255,101,167) */

static int cs_is_dark(uint32_t c) {
    return cs_channel_diff(c, 0xFF000000u) <= 12;
}
static int cs_is_bg(uint32_t c) {
    return cs_channel_diff(c, CS_BG_COLOR) <= 12;
}
static int cs_is_pink(uint32_t c) {
    return cs_channel_diff(c, CS_PINK_COLOR) <= 12;
}

int ne_detect_char_select_page1(const uint32_t *frame, int w, int h) {
    if (!frame || w < 256 || h < 240) return 0;
    if (!cs_is_pink(frame[0]) || !cs_is_pink(frame[(size_t)236 * w + 252])) return 0;
    if (!cs_is_bg(frame[(size_t)90 * w + 45])) return 0;
    if (!cs_is_dark(frame[(size_t)90 * w + 178])) return 0;
    if (!cs_is_bg(frame[(size_t)204 * w + 68])) return 0;
    return 1;
}

int ne_detect_char_select_page2(const uint32_t *frame, int w, int h) {
    if (!frame || w < 256 || h < 240) return 0;
    if (!cs_is_pink(frame[0]) || !cs_is_pink(frame[(size_t)236 * w + 252])) return 0;
    if (!cs_is_bg(frame[(size_t)90 * w + 45])) return 0;
    if (!cs_is_dark(frame[(size_t)204 * w + 68])) return 0;
    if (!cs_is_dark(frame[(size_t)203 * w + 190])) return 0;
    if (!cs_is_bg(frame[(size_t)200 * w + 47])) return 0;
    return 1;
}

int ne_detect_char_select_page3(const uint32_t *frame, int w, int h) {
    if (!frame || w < 256 || h < 240) return 0;
    if (!cs_is_pink(frame[0]) || !cs_is_pink(frame[(size_t)236 * w + 252])) return 0;
    if (!cs_is_bg(frame[(size_t)202 * w + 50])) return 0;
    if (!cs_is_bg(frame[(size_t)204 * w + 68])) return 0;
    if (!cs_is_bg(frame[(size_t)90 * w + 178])) return 0;
    return 1;
}

int ne_detect_char_select_page4(const uint32_t *frame, int w, int h) {
    if (!frame || w < 256 || h < 240) return 0;
    if (!cs_is_pink(frame[0]) || !cs_is_pink(frame[(size_t)236 * w + 252])) return 0;
    if (!cs_is_dark(frame[(size_t)90 * w + 45])) return 0;
    if (!cs_is_dark(frame[(size_t)90 * w + 178])) return 0;
    return 1;
}

int ne_detect_char_select_page5(const uint32_t *frame, int w, int h) {
    if (!frame || w < 256 || h < 240) return 0;
    if (!cs_is_pink(frame[0]) || !cs_is_pink(frame[(size_t)236 * w + 252])) return 0;
    if (!cs_is_dark(frame[(size_t)200 * w + 47])) return 0;
    if (!cs_is_dark(frame[(size_t)200 * w + 111])) return 0;
    if (!cs_is_dark(frame[(size_t)200 * w + 175])) return 0;
    return 1;
}

/* Page identifier: returns 1-5 for pages 1-5, 0 for unknown/non-char-select.
 * Detection order: 5 -> 4 -> 3 -> 2 -> 1 (most specific first). */
int ne_detect_char_select_page(const uint32_t *frame, int w, int h) {
    if (!frame || w < 256 || h < 240) return 0;
    if (ne_detect_char_select_page5(frame, w, h)) return 5;
    if (ne_detect_char_select_page4(frame, w, h)) return 4;
    if (ne_detect_char_select_page3(frame, w, h)) return 3;
    if (ne_detect_char_select_page2(frame, w, h)) return 2;
    if (ne_detect_char_select_page1(frame, w, h)) return 1;
    return 0;
}


/* ---- Match-flow (versus) screen detector ----
 *
 * Detects the verified yokozuna dialogue screen (cyc_shot_0003.png).
 * Uses a complete binary template of the two-line text region (foreground
 * glyph pixels AND background pixels) combined with layout checks.
 * Re-evaluated every call; no state/latching.
 *
 * Template region: x=40..160, y=152..176 (121x25), foreground=green (0,95,0),
 * background=yellow (232,173,0). Layout: green bg at corner + yellow box at (36,144).
 */

#define MV_GREEN 0xFF005F00u  /* (0,95,0) in ARGB */
#define MV_YELLOW 0xFFE8AD00u /* (232,173,0) in ARGB */

static const uint8_t s_mv_template[25][16] = {
    {0x20, 0x40, 0x20, 0x00, 0x40, 0x00, 0x20, 0x84, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80},
    {0xFC, 0x5C, 0x7C, 0x00, 0x84, 0x3C, 0x24, 0xBE, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80},
    {0x22, 0xE2, 0x20, 0x00, 0x82, 0xC2, 0xFA, 0x84, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80},
    {0x7C, 0x62, 0xFC, 0x00, 0x82, 0x02, 0x2A, 0x84, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80},
    {0xA2, 0xC4, 0x40, 0x00, 0x82, 0x02, 0x4A, 0x9E, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80},
    {0xA2, 0xC8, 0x42, 0x00, 0xA6, 0x04, 0x48, 0xA4, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80},
    {0x64, 0x46, 0x3C, 0x00, 0x40, 0x38, 0x98, 0x98, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80},
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80},
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80},
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00},
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00},
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00},
    {0x00, 0x00, 0x14, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x14, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00},
    {0x00, 0x00, 0x14, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x14, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00},
    {0x00, 0x00, 0x14, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x14, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00},
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80},
    {0x20, 0x00, 0x00, 0x20, 0x00, 0x00, 0x20, 0x7C, 0x10, 0x20, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80},
    {0x3C, 0x7C, 0x3C, 0xF8, 0x9E, 0x00, 0xF8, 0x08, 0x10, 0xFC, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80},
    {0x20, 0x08, 0xC2, 0x46, 0x84, 0x00, 0x46, 0x3C, 0x20, 0x20, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80},
    {0x10, 0x00, 0x02, 0x44, 0x80, 0x00, 0x44, 0xC2, 0x30, 0x4E, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80},
    {0x7C, 0x40, 0x02, 0x9C, 0x90, 0x00, 0x9C, 0x32, 0x4A, 0x40, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80},
    {0x8A, 0x80, 0x04, 0xA6, 0xD0, 0x00, 0xA6, 0x4A, 0x4A, 0x90, 0xC0, 0xC0, 0xC0, 0x00, 0x00, 0x80},
    {0x70, 0x7E, 0x38, 0x1C, 0x8E, 0x00, 0x1C, 0x3C, 0x84, 0x8E, 0xC0, 0xC0, 0xC0, 0x00, 0x00, 0x80},
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80},
    {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x80},
};

#define MV_TX0 40
#define MV_TY0 152
#define MV_TX1 160
#define MV_TY1 176
#define MV_TW  121
#define MV_TH  25

int ne_detect_match_versus(const uint32_t *frame, int w, int h) {
    if (!frame || w < 256 || h < 240) return 0;

    if (frame[0] != MV_GREEN) return 0;
    if (frame[(size_t)144 * (size_t)w + 36] != MV_YELLOW) return 0;

    if (MV_TX0 < 0 || MV_TY0 < 0 || MV_TX1 >= w || MV_TY1 >= h) return 0;

    for (int row = 0; row < MV_TH; ++row) {
        for (int col = 0; col < MV_TW; ++col) {
            int x = MV_TX0 + col;
            int y = MV_TY0 + row;
            uint32_t pixel = frame[(size_t)y * (size_t)w + (size_t)x];
            int bit = (s_mv_template[row][col / 8] >> (7 - (col % 8))) & 1;
            int is_fg = (pixel == MV_GREEN) ? 1 : 0;
            if (is_fg != bit) return 0;
        }
    }
    return 1;
}


/* ---- Title menu (START/CONTINUE) detector ----
 *
 * Detects the initial title menu state. Uses binary templates of both
 * label rows (x=128-157, y=200-206 and x=128-182, y=216-222) plus
 * layout checks (light blue bg at corner, title logo presence).
 * Re-evaluated every call; no state/latching.
 */

#define TM_BG 0xFFC0D8FFu   /* light blue (192,216,255) */
#define TM_BLACK 0xFF000000u

/* Row 1 template: 30x7 (????) */
static const uint8_t s_tm_row1[7][4] = {
    {0x08, 0x20, 0x00, 0x40},
    {0xFE, 0xFC, 0x00, 0x4C},
    {0x38, 0x20, 0x00, 0x70},
    {0x48, 0x4E, 0xFE, 0x40},
    {0x38, 0x40, 0x00, 0x80},
    {0x08, 0x90, 0x00, 0x80},
    {0x30, 0x8E, 0x00, 0x7C},
};

/* Row 2 template: 55x7 (???????) */
static const uint8_t s_tm_row2[7][7] = {
    {0x00, 0x10, 0x00, 0x00, 0x00, 0x00, 0x00},
    {0x7C, 0x10, 0xFE, 0x00, 0x9E, 0x00, 0x00},
    {0x08, 0x20, 0x18, 0x00, 0x84, 0x10, 0x00},
    {0x00, 0x30, 0x20, 0x48, 0x80, 0x78, 0xFE},
    {0x40, 0x4A, 0x40, 0x44, 0x90, 0x54, 0x00},
    {0x80, 0x4A, 0x40, 0x54, 0xD0, 0x18, 0x00},
    {0x7E, 0x84, 0x3C, 0x20, 0x8E, 0x20, 0x00},
};

#define TM_ROW1_X0 128
#define TM_ROW1_Y0 200
#define TM_ROW1_W  30
#define TM_ROW1_H  7
#define TM_ROW2_X0 128
#define TM_ROW2_Y0 216
#define TM_ROW2_W  55
#define TM_ROW2_H  7

int ne_detect_title_menu(const uint32_t *frame, int w, int h) {
    if (!frame || w < 256 || h < 240) return 0;

    /* Layout check: light blue background at corner */
    if (frame[0] != TM_BG) return 0;

    /* Layout check: title logo presence (black pixel at known position) */
    if (frame[(size_t)45 * (size_t)w + 100] != TM_BLACK) return 0;

    /* Bounds validation */
    if (TM_ROW1_X0 + TM_ROW1_W > w || TM_ROW1_Y0 + TM_ROW1_H > h) return 0;
    if (TM_ROW2_X0 + TM_ROW2_W > w || TM_ROW2_Y0 + TM_ROW2_H > h) return 0;

    /* Template match Row 1 */
    for (int row = 0; row < TM_ROW1_H; ++row) {
        for (int col = 0; col < TM_ROW1_W; ++col) {
            int x = TM_ROW1_X0 + col;
            int y = TM_ROW1_Y0 + row;
            uint32_t pixel = frame[(size_t)y * (size_t)w + (size_t)x];
            int bit = (s_tm_row1[row][col / 8] >> (7 - (col % 8))) & 1;
            int is_fg = (pixel == TM_BLACK) ? 1 : 0;
            if (is_fg != bit) return 0;
        }
    }

    /* Template match Row 2 */
    for (int row = 0; row < TM_ROW2_H; ++row) {
        for (int col = 0; col < TM_ROW2_W; ++col) {
            int x = TM_ROW2_X0 + col;
            int y = TM_ROW2_Y0 + row;
            uint32_t pixel = frame[(size_t)y * (size_t)w + (size_t)x];
            int bit = (s_tm_row2[row][col / 8] >> (7 - (col % 8))) & 1;
            int is_fg = (pixel == TM_BLACK) ? 1 : 0;
            if (is_fg != bit) return 0;
        }
    }
    return 1;
}


