int ne_detect_m78_team(const uint32_t *frame, int w, int h)
{
    if (!frame || w != 256 || h != 240)
        return 0;

    for (size_t i = 0;
         i < sizeof(s_m78_checks)/sizeof(s_m78_checks[0]);
         ++i) {
        const struct m78_check *p = &s_m78_checks[i];

        if (frame[(size_t)p->y*w+p->x] != p->color)
            return 0;
    }

    return 1;
}


