static int m78_match_pixels(
    const uint32_t *frame, int w, int h,
    const struct m78_state_pixel *checks, size_t count)
{
    if (!frame || w != 256 || h != 240)
        return 0;

    for (size_t i = 0; i < count; ++i) {
        const struct m78_state_pixel *p = &checks[i];

        if (frame[(size_t)p->y*w+p->x] != p->color)
            return 0;
    }

    return 1;
}

int ne_detect_m78_overview(const uint32_t *frame, int w, int h)
{
    return m78_match_pixels(
        frame,w,h,
        s_m78_overview_pixels,
        sizeof(s_m78_overview_pixels)/
        sizeof(s_m78_overview_pixels[0]));
}

int ne_detect_m78_order(const uint32_t *frame, int w, int h)
{
    return m78_match_pixels(
        frame,w,h,
        s_m78_order_pixels,
        sizeof(s_m78_order_pixels)/
        sizeof(s_m78_order_pixels[0]));
}


/* Green four-bubble pre-match dialogue screen.
 * All checks use the original 256x240 ARGB frame.
 */
int ne_detect_green_dialogue(const uint32_t *frame, int w, int h)
{
    if (!frame || w != 256 || h != 240)
        return 0;

    const uint32_t green = 0xFF179E00u;
    const uint32_t white = 0xFFFFFFFFu;

    /* Green field and white bubble interiors. */
    if (frame[(size_t)80*w+128] != green) return 0;
    if (frame[(size_t)100*w+128] != green) return 0;
    if (frame[(size_t)220*w+128] != green) return 0;

    if (frame[(size_t)35*w+70] != white) return 0;
    if (frame[(size_t)35*w+145] != white) return 0;
    if (frame[(size_t)205*w+35] != white) return 0;
    if (frame[(size_t)205*w+220] != white) return 0;

    return 1;
}


