int ne_detect_verified_dialogue(
    const uint32_t *frame, int w, int h)
{
    if (!frame || w != 256 || h != 240)
        return 0;

    if (!ne_detect_green_dialogue(frame,w,h))
        return 0;

    for (size_t i=0;
         i<sizeof(s_verified_dialogue)/
           sizeof(s_verified_dialogue[0]);
         ++i) {
        const DialogueCheck *p = &s_verified_dialogue[i];

        if (frame[(size_t)p->y*w+p->x] != p->color)
            return 0;
    }

    return 1;
}
